PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS collections(id INTEGER PRIMARY KEY,root_path TEXT NOT NULL UNIQUE,added_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS files(id INTEGER PRIMARY KEY,collection_id INTEGER NOT NULL REFERENCES collections(id) ON DELETE CASCADE,path TEXT NOT NULL UNIQUE,name TEXT NOT NULL,extension TEXT NOT NULL,size INTEGER NOT NULL DEFAULT 0,modified REAL NOT NULL DEFAULT 0,sha256 TEXT,text_content TEXT NOT NULL DEFAULT '',indexed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_files_collection ON files(collection_id);
CREATE INDEX IF NOT EXISTS idx_files_hash ON files(sha256);
CREATE TABLE IF NOT EXISTS connections(id INTEGER PRIMARY KEY,source_id INTEGER NOT NULL REFERENCES files(id) ON DELETE CASCADE,target_id INTEGER NOT NULL REFERENCES files(id) ON DELETE CASCADE,kind TEXT NOT NULL,reason TEXT NOT NULL,score REAL NOT NULL DEFAULT 0,UNIQUE(source_id,target_id,kind,reason));
